import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BN3Eol-0.js";const g=JSON.parse('{"title":"UXD-012 — One page shell: container, title, lead and section label for every text page","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-012-one-page-shell.md","filePath":"uxs/decisions/UXD-012-one-page-shell.md"}'),i={name:"uxs/decisions/UXD-012-one-page-shell.md"};function n(l,e,c,d,r,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="uxd-012-—-one-page-shell-container-title-lead-and-section-label-for-every-text-page" tabindex="-1">UXD-012 — One page shell: container, title, lead and section label for every text page <a class="header-anchor" href="#uxd-012-—-one-page-shell-container-title-lead-and-section-label-for-every-text-page" aria-label="Permalink to &quot;UXD-012 — One page shell: container, title, lead and section label for every text page&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted</li><li><strong>Date</strong>: 2026-11-11 (proposed and decided)</li><li><strong>Decider</strong>: the operator — &quot;I agree with all recommendations to 1-6&quot; on the six slice A2 questions (<code>docs/wip/2026-11-11-ux-feedback-plan.md</code>, line starting &quot;- A2 page shell (operator 2026-11-11&quot;); inputs RP1 (&quot;All pages share one style, vibe and standard approach. For fonts, Gallery is the best so far&quot;), CR1, LI1, G1, G2, G5</li><li><strong>Answers</strong>: RP1, CR1, LI1, G1, G2, G5; slice A2</li><li><strong>Changes</strong>: <code>src/lib/styles/page-shell.css</code> (new, loaded by <code>app.css</code>); <code>tokens.css</code><code>--size-title</code>; <a href="./../IA">IA §page-shell</a>; Design System §3.2, §3.3, §4.6, §5.8 (<code>docs/concept/05_Design_System.md</code>); AGENTS.md &quot;Design system&quot; block; <code>docs/adr/TA.md</code> type-scale paragraph; <code>src/lib/components/README.md</code></li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Before A2, 27 files drew 32 text pages with ten h1 sizes (28 px to 72 px), seven lead sizes (14–20 px), ten container widths (720–1400 px), centred headers on two pages and three pages (<code>/gallery</code>, <code>/patches</code>, <code>/sourcing</code>) that added the nav height on top of the sticky nav, so their title started about 64 px lower than everywhere else. Full inventory: <code>docs/wip/2026-11-11-slice-A2-brief.md</code> §1.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><ol><li>One CSS file of shared classes, values from Gallery (the operator&#39;s reference) and the design system. 2. A <code>PageShell.svelte</code> component (rewrites the markup of 27 files and their test hooks). 3. Keep per-page CSS and add a test only.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Option 1. <code>.page-shell</code> 1080 px, centred, 24 px top, 20 px sides, 80 px bottom; <code>--reading</code> 760 px; <code>--wide</code> 1400 px; <code>--inset</code> inside the science host layout. <code>.page-title</code> Bebas Neue <code>clamp(40px, 8vw, 64px)</code>, 1 px spacing. <code>.page-lead</code> <code>--size-lead</code> upright Space Mono, 78 % white, 64ch. <code>.page-section-label</code> Space Mono 11 px 700 uppercase 3 px spacing 60 % white (Q1: replaces the 12 px <code>#7fb0e0</code> labels). <code>.page-section-title</code> Bebas 28 px. No page adds <code>--nav-height</code>. The six answers: (1) design-system section label; (2) the gallery strip text starts on the title&#39;s left edge, the strip a band with square left corners; (3) program pages move from Crimson to Space Mono, long-form essay and science prose keeps upright Crimson; (4) missions, launches and fleet stay tools with no visible title; (5) the standard text white replaces the bluish <code>#dde4ff</code> / <code>#dfe6f2</code>; (6) the four hubs widen to 1080 px.</p><p>Not on the shell: the home page (home slice, H8), scene routes, the Lab, the browse tools, card stubs, dev pages. Kept exceptions in the code carry <code>a2-keep: &lt;why&gt;</code> (strip card titles, the lightbox title, essay prose headings, privacy card titles, the programs toolbar hint, the TV hub layout, link colours that slice A3 owns).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The pages lose their private h1, lead and container rules. Visible changes: entity pages (missions, fleet, sites, bodies, Lab formulas) get the Bebas title instead of a Space Mono one; deep-sky and posters headers are left-aligned instead of centred; the science glossary, reading and watch lists lose the gold title and teal section headings for white ones; colophon, credits, library and the hubs change title size. No text or locale change.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p><code>tests/e2e/page-shell.spec.ts</code> (every shell page: root under the nav with 24 px, h1 family, size and spacing, lead family, size and upright, title on the content edge, the G1 strip edge, home not on the shell), run on desktop-chromium, mobile-chromium and mobile-landscape-chromium. The slice check script (<code>A2-CHECK</code>, brief §10) prints <code>A2-CHECK violations: 0</code>.</p>',13)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
